const headers = $input.item.json.headers || {};
const body = $input.item.json.body || {};

const expectedSecret = $env.WEBHOOK_SECRET || "bookleaf_secure_webhook_secret_2026";
const providedSecret = headers["x-webhook-secret"] || headers["X-Webhook-Secret"];

if (!providedSecret || providedSecret !== expectedSecret) {
  return [{
    json: {
      is_valid: false,
      status_code: 401,
      error: "Unauthorized: Invalid or missing X-Webhook-Secret header",
      request_id: body.request_id || "UNKNOWN"
    }
  }];
}

if (!body.request_id || !body.author_id) {
  return [{
    json: {
      is_valid: false,
      status_code: 400,
      error: "Bad Request: Missing request_id or author_id in payload",
      request_id: body.request_id || "UNKNOWN"
    }
  }];
}

return [{
  json: {
    is_valid: true,
    request_id: body.request_id,
    author_id: body.author_id,
    author_name: body.author_name || "Author",
    author_email: body.author_email || "",
    triggered_by: body.triggered_by || "admin@bookleaf.com",
    triggered_at: body.triggered_at || new Date().toISOString()
  }
}];

const authData = $("Validate Auth & Payload").item.json;
const authorRaw = $("Fetch Author from Bubble").item.json;
const booksRaw = $input.item.json;

// Handle both live Bubble API response structure and mock/local response
const authorResult = (authorRaw.response && authorRaw.response.results && authorRaw.response.results[0]) || authorRaw;
const booksList = (booksRaw.response && booksRaw.response.results) || (Array.isArray(booksRaw) ? booksRaw : []);

let totalSold = 0;
let totalEarned = 0;
let totalPaid = 0;
let totalPending = 0;

let publishedBooks = [];
let productionBooks = [];

booksList.forEach(book => {
  const sold = Number(book.total_copies_sold || 0);
  const earned = Number(book.total_royalty_earned || 0);
  const paid = Number(book.royalty_paid || 0);
  const pending = Number(book.royalty_pending || 0);

  totalSold += sold;
  totalEarned += earned;
  totalPaid += paid;
  totalPending += pending;

  if (book.status && book.status.toLowerCase().includes("production")) {
    productionBooks.push({
      title: book.title,
      status: book.status,
      milestone: book.status.replace("In Production - ", "")
    });
  } else {
    publishedBooks.push({
      title: book.title,
      isbn: book.isbn || "N/A",
      genre: book.genre || "General",
      copies_sold: sold,
      royalty_earned: earned,
      royalty_paid: paid,
      royalty_pending: pending,
      last_payout: book.last_royalty_payout_date || "None recorded yet",
      platforms: book.available_on_raw || "Amazon India, BookLeaf Store"
    });
  }
});

// Determine Status Badge
let statusCategory = "YELLOW";
if (totalPending === 0) {
  statusCategory = "GREEN";
} else {
  const now = new Date();
  const ninetyDaysAgo = new Date(now.getTime() - (90 * 24 * 60 * 60 * 1000));
  const hasOverdueBook = publishedBooks.some(b => {
    if (b.royalty_pending > 0 && b.last_payout !== "None recorded yet") {
      return new Date(b.last_payout) < ninetyDaysAgo;
    }
    return false;
  });
  if (hasOverdueBook) {
    statusCategory = "RED";
  }
}

const isSubThreshold = totalPending > 0 && totalPending < 1000;

// Build text block for LLM prompt
let booksFormatted = "PUBLISHED TITLES:\n";
if (publishedBooks.length === 0) {
  booksFormatted += "None. All books currently in production.\n";
} else {
  publishedBooks.forEach((b, i) => {
    booksFormatted += `${i+1}. "${b.title}" | Copies Sold: ${b.copies_sold} | Earned: ₹${b.royalty_earned} | Paid: ₹${b.royalty_paid} | Pending: ₹${b.royalty_pending} | Last Payout: ${b.last_payout}\n`;
  });
}

if (productionBooks.length > 0) {
  booksFormatted += "\nTITLES IN PRODUCTION:\n";
  productionBooks.forEach((b, i) => {
    booksFormatted += `${i+1}. "${b.title}" (Current Stage: ${b.status}) - Royalties will begin tracking immediately upon live release.\n`;
  });
}

let policyInstructions = "- Standard 80/20 royalty split applies.\n- Payouts occur quarterly within 45 days after quarter end via bank transfer.\n";
if (isSubThreshold) {
  policyInstructions += `- NOTE: Total pending amount of ₹${totalPending} is below the ₹1,000 threshold. It will roll over intact to next quarter.\n`;
} else if (totalPending === 0) {
  policyInstructions += "- NOTE: All royalties have been disbursed (₹0 pending). Acknowledge this with appreciation.\n";
} else {
  policyInstructions += `- NOTE: Pending amount of ₹${totalPending} exceeds ₹1,000 threshold and qualifies for the upcoming quarterly disbursement.\n`;
}

return [{
  json: {
    request_id: authData.request_id,
    author_id: authData.author_id,
    author_name: authorResult.name || authData.author_name,
    author_email: authorResult.email || authData.author_email,
    author_city: authorResult.city || "India",
    totals: {
      total_copies_sold: totalSold,
      total_royalty_earned: totalEarned,
      total_royalty_paid: totalPaid,
      total_royalty_pending: totalPending
    },
    status_category: statusCategory,
    is_sub_threshold: isSubThreshold,
    books_formatted_list: booksFormatted,
    policy_instructions: policyInstructions
  }
}];

