const calc = $("Deterministic Aggregator & Policies").item.json;
const llmRaw = $input.item.json;

try {
  let responseObj = null;
  if (llmRaw.choices && llmRaw.choices[0] && llmRaw.choices[0].message) {
    const content = llmRaw.choices[0].message.content;
    responseObj = JSON.parse(content);
  } else if (llmRaw.email_body) {
    responseObj = llmRaw;
  } else {
    throw new Error("LLM response missing choices or content structure");
  }

  if (!responseObj.email_subject || !responseObj.email_body) {
    throw new Error("AI response missing email_subject or email_body");
  }

  return [{
    json: {
      is_success: true,
      request_id: calc.request_id,
      author_id: calc.author_id,
      email_subject: responseObj.email_subject,
      email_body: responseObj.email_body,
      total_earned: calc.totals.total_royalty_earned,
      total_paid: calc.totals.total_royalty_paid,
      total_pending: calc.totals.total_royalty_pending
    }
  }];
} catch (err) {
  return [{
    json: {
      is_success: false,
      request_id: calc.request_id,
      author_id: calc.author_id,
      error_message: "Failed to parse or validate AI output: " + err.message
    }
  }];
}
